    designfluency: { t: "Design Fluency", b: "I'm a trained service designer with a background in operations and leading teams. My fluency in design work allows me to ask the right questions and spot risk early, because I've built the blueprints, run the research, and facilitated the workshops myself.", s: "7+ years experience" },
    /* -- Research & Discovery -- */
